export function readingSheetStops({width,height,header=104,footer=60,landscape=false}) {
  if (landscape) return {collapsed:44,peek:Math.max(220,width*.32),expanded:width};
  const expanded=Math.max(150,height-header-footer-12);
  return {collapsed:44,peek:Math.min(expanded,Math.max(170,Math.min(230,height*.27))),expanded};
}
export function settleReadingSheet(extent, velocity, stops) {
  // A short flick projects the same drag forward. It never moves the camera.
  const projected=Math.max(stops.collapsed,Math.min(stops.expanded,extent+velocity*140));
  return Object.keys(stops).reduce((best,key)=>Math.abs(stops[key]-projected)<Math.abs(stops[best]-projected)?key:best,'collapsed');
}
